  ui_story_31050201_64_dialog_content = "<color=#e8d9bb>Un saco de pólvora cae al suelo.</color>",
  ui_story_31050201_65_dialog_content = "Viniste por estas cosas.",
  ui_story_31050201_66_dialog_content = "Yo-yo-yo puedo explicar...",
