  ui_story_31050201_88_dialog_content = "No es una bomba...",
  ui_story_31050201_89_dialog_content = "Además, esto no es algo que una pequeña como tú debas manejar, y... ¿Eh?",
  ui_story_31050201_90_dialog_content = "Yo... ¡Solo quería que Joanie me ayudara a hacer algunos <color=#FFB400>fuegos artificiales</color> para Dawn...!",
  ui_story_31050201_91_dialog_content = "Fuegos artificiales... ¿Por qué quieres hacerlos de repente?",
  ui_story_31050201_92_dialog_content = "¿Recuerdas lo que te dije antes, que soy de <color=#FFB400>Red-Eye Gorge</color>?",
  ui_story_31050201_93_dialog_content = "Si, más o menos...",
  ui_story_31050201_94_dialog_content = "Bueno, siem. que había un día festivo en nues. pueblo, ¡poníamos fuegos artificiales para celebrar!",
  ui_story_31050201_95_dialog_content = "¡En esos días festivos, nos sen. con nuestras fam. y comíamos bocadillos mien. veíamos los fuegos artificiales!",
  ui_story_31050201_96_dialog_content = "¡Antes, me sentaba en el regazo de mis padres y Sinsa me pelaba naranjas para que las comiera!",
  ui_story_31050201_97_dialog_content = "Todas esas lindas luces estallando en el cielo nocturno, luego cayendo como miles de estrellas fugaces... Tenía ganas de pedir un deseo con cada uno de ellos.",
  ui_story_31050201_98_dialog_content = "Eran tiempos felices...",
  ui_story_31050201_99_dialog_content = "Ent., cada vez que veo fuegos artificiales, rec. todas las caras sonrientes de ese entonces.",
  ui_story_31050201_100_option_content = "Suena como un momento maravilloso.",
  ui_story_31050201_101_dialog_content = "\"Fuegos artificiales estallando en el cielo noc.\"... Me encantaría ver algo así también.",
  ui_story_31050201_102_dialog_content = "¿Cierto? ¡Sabía que nadie podía decir que no a los fuegos artificiales!",
  ui_story_31050201_103_option_content = "Suena... ¿Lindo?",
  ui_story_31050201_104_dialog_content = "¡¿Simplemente “agradable\"?! ¿Alguna vez has visto fuegos artificiales? ¡Lo entenderías si lo hicieras!",
  ui_story_31050201_105_dialog_content = "¿Cierto? ¡Sabía que nadie podía decir que no a los fuegos artificiales!",
  ui_story_31050201_106_dialog_content = "De alguna man. me convenciste.",
  ui_story_31050201_107_dialog_content = "¡Solo confía en mí! ¡También le conté a <color=#FFB400>Dawn</color> sobre los fuegos artificiales!",
  ui_story_31050201_108_dialog_content = "Siempre que me esc. hablar de ellos, siempre tenía esa expresión de tristeza y envidia en su rostro...",
  ui_story_31050201_109_dialog_content = "Pero cada vez que le preg. al respecto, ella sim. me decía que no era nada especial...",
  ui_story_31050201_110_dialog_content = "Sé que quiere verlos, pero no quiere entris. sacando a relucir el pasado...",
  ui_story_31050201_111_dialog_content = "¡Pero las cosas son dif. ahora! Me ayudarás, ¿verdad...?",
  ui_story_31050201_112_dialog_content = "Bueno, cuando me miras así...",
  ui_story_31050201_113_option_content = "¿Cómo podría decir que no?",
  ui_story_31050201_114_dialog_content = "Bien... Mientras el Colossus no esté en peligro, lo permitiré. ¡Pero ustedes dos deben tener cuidado de no lastimarse!",
  ui_story_31050201_115_dialog_content = "¡Hurra! ¡Ten. cuidado, lo prometo! ¡Nos. también tenemos un plan!",
  ui_story_31050201_116_dialog_content = "¿D-De verdad...? De repente me empiezo a preocupar...",
  ui_story_31050201_117_dialog_content = "Ya somos dos.",
  ui_story_31050201_114_option_content = "Todavía tengo mis reservas...",
  ui_story_31050201_119_dialog_content = "¡Prometo que no last. a Soroz de ninguna manera! ¡Lo juro!",
  ui_story_31050201_120_dialog_content = "Soroz no es el único en peligro. Su seg. también es importante.",
  ui_story_31050201_121_dialog_content = "*Suspiro* Todavía estoy un poco preo., pero como es Eve...",
  ui_story_31050201_122_dialog_content = "De todos modos, ¿por qué hacer fuegos art. para Dawn?",
  ui_story_31050201_123_dialog_content = "Bien... ¡Dawn es mi mejor amiga y siempre me cuida! Incluso durante la peor parte de nues. vidas, ella me man. abrigada y segura...",
  ui_story_31050201_124_dialog_content = "Pero cuando lo pienso, no he hecho nada por ella ...",
  ui_story_31050201_125_dialog_content = "Así que pensé esta vez, ¡le daré la cosa <color=#FFB400>más cálida</color> que se me ocurra!",
  ui_story_31050201_126_dialog_content = "Así que fui a pedirle ayuda a Joanie, pero ella me dijo que le prohibiste el almacén... Por eso yo...",
  ui_story_31050201_127_dialog_content = "Eso es cierto, yo...",
  ui_story_31050201_128_dialog_content = "¡Por eso vine aquí! ¡Para cons. todo lo que Joanie nec. para los fuegos artificiales!",
  ui_story_31050201_129_dialog_content = "(Joanie es bas. pelig., después de todo. Incluso reclutó a una niña para que la ayude esta vez...)",
  ui_story_31050201_130_dialog_content = "Corrígeme si me equivoco, pero... ¿No es Dawn <color=#FFB400>ciega</color>?",
  ui_story_31050201_131_dialog_content = "¿De qué sirve hacer fuegos art. para ella, si ni siq. puede verlos...?",
  ui_story_31050201_132_dialog_content = "Yo también pensé en eso. Sentí que era solo una ilusión...",
  ui_story_31050201_133_dialog_content = "Y me preo. que Dawn pensara que también era inútil...",
  ui_story_31050201_134_dialog_content = "Pero luego, pensé... ¡No deberías nec. ver algo que haga que todos se sientan felices para sentir lo mismo!",
  ui_story_31050201_135_dialog_content = "*Suspiro* Ya que lo pones de esa manera, Eve...",
  ui_story_31050201_136_dialog_content = "No me imp. ver a Dawn más feliz aunque solo fuera un poco... ¡Pero debes tener mucho cuidado!",
  ui_story_31050201_137_dialog_content = "¡No te preocupes! Joanie y yo ya hab. de ello, ¡y prometo que no haremos peligrosos fuegos artificiales!",
  ui_story_31050201_138_dialog_content = "Mmm... Sabes, hubiera sido más fácil pedir mi ayuda en primer lugar. ¿Por qué tanto andar a escondidas?",
  ui_story_31050201_139_dialog_content = "P-Porque... Quería sorprender a Dawn.",
  ui_story_31050201_140_dialog_content = "Sentí que si te lo dijera, se lo dirías a los demás de inmediato...",
  ui_story_31050201_141_dialog_content = "¿Eve piensa en mí de esa manera?...",
  ui_story_31050201_142_dialog_content = "Además, no queríamos decepcionar a nadie si hacíamos un mal trabajo... ¡Así que quer. aseg. de que todo estaba bien antes de decírselo a alguien!",
  ui_story_31050201_143_dialog_content = "No te preocupes. Incluso sin los fuegos art., estoy seguro de que ten. muchas otras formas de hacer feliz a Dawn.",
  ui_story_31050201_144_dialog_content = "Sabes mucho para tu edad, Eve...",
  ui_story_31050201_145_dialog_content = "<color=#e8d9bb>Extiende la mano y le das una palmadita a Eve en la cabeza.</color>",
  ui_story_31050201_146_dialog_content = "Aun así, quiero que esto sea un gran éxito... ¡No fallaré!",
  ui_story_31050201_147_dialog_content = "¡Yo tam. ayudaré!",
  ui_story_31050201_X147_dialog_content = "¡No me mires así! ¡Prom. que no se lo diré a nadie!",
  ui_story_31050201_148_dialog_content = "De todos modos, ¿cuándo planeas mostrarle a Dawn los fuegos art.?",
  ui_story_31050201_149_dialog_content = "<color=#e8d9bb>Eve se lleva un dedo a los labios.</color>",
  ui_story_31050201_150_dialog_content = "¡No puedo decirte aún!",
  ui_story_31050201_151_dialog_content = "Des. de todo, ¡sigue siendo una gran sorpresa!",
  ui_story_31050201_152_dialog_content = "Sigues pensando que lo diré, ¿no?",
  ui_story_31050201_153_dialog_content = "Quizá sólo un poco...",
  ui_story_31050201_154_dialog_content = "Aunque todavía estoy un poco preocupado... Confío en ti, Eve. ¡Sé que no harás nada peligroso!",
  ui_story_31050201_155_dialog_content = "¡Déjamelo a mí! ¡Tú también te sorprenderás mucho!",
  ui_story_31050601_1_dialog_content = "El X",
  ui_story_31050601_2_dialog_content = "Concurso de popularidad de la llave inglesa Rediesel",
  ui_story_31050601_3_dialog_content = "Etapa del concurso",
  ui_story_31050601_4_dialog_content = "<color=#e8d9bb>Tres horas antes del concurso...</color>",
  ui_story_31050601_5_dialog_content = "¡Próximo set de ensayo general! El equipo detrás del escenario, ¿a dónde han ido?",
  ui_story_31050601_6_dialog_content = "¿Ustedes no saben leer? ¡Párate en tu marca del escenario, todos ustedes! ¡De lo contrario, el centro de atención no puede seguirte!",
  ui_story_31050601_7_dialog_content = "¿Alguien ha visto a Regina? ¡¡Dile que venga al backstage a devolverle el auricular!!",
  ui_story_31050601_8_dialog_content = "Comprobación de micrófono, uno-dos, uno-dos... Probando, probando, uno-dos-tres...",
  ui_story_31050601_9_dialog_content = "Cálmate, solo respira... Cálmate, solo respira... Cálmate, solo... Oh no...",
  ui_story_31050601_10_dialog_content = "...",
  ui_story_31050601_11_dialog_content = "Guau, el concurso ni siquiera ha comenzado, y todos ya están tan ocupados como pueden estar.",
  ui_story_31050601_12_dialog_content = "<color=#e8d9bb>Ka-thunk!!</color>",
  ui_story_31050601_13_dialog_content = "¡¡E-Esa es una enorme caja de fuegos artificiales!!",
  ui_story_31050601_14_dialog_content = "Oye, trata de mantenerte fuera del camino. Es fácil lastimarse por aquí.",
  ui_story_31050601_15_dialog_content = "¡Ay! Uh, lo siento por eso...",
  ui_story_31050601_16_dialog_content = "Debería ir a esperar a otro lado...",
  ui_story_31050601_17_dialog_content = "Vaya... Esto debería ser suficiente, ¿verdad?",
  ui_story_31050601_18_dialog_content = "Ahora que lo pienso... ¿Por qué estoy aquí, en primer lugar?",
  ui_story_31050601_19_dialog_content = "...",
  ui_story_31050601_20_dialog_content = "¿Mmm?",
  ui_story_31050601_21_dialog_content = "Ve, ve, haz tu... ¿lo mejor? No... Sigue y...",
  ui_story_31050601_22_dialog_content = "No, ninguno de estos suena bien en absoluto...",
  ui_story_31050601_23_dialog_content = "Te encontré.",
  ui_story_31050601_24_dialog_content = "...",
  ui_story_31050601_25_dialog_content = "Ejem.",
  ui_story_31050601_26_dialog_content = "¿Eh? ¿Quién está ahí?",
  ui_story_31050601_27_dialog_content = "¡Ajá! ¡Sabía que eras tú, Eva!",
  ui_story_31050601_28_dialog_content = "PlayerName?! Oh... Así es, tú también estás en el concurso...",
  ui_story_31050601_29_dialog_content = "Sí, me presenté al ensayo, pero... Parece que nadie sigue las instrucciones.",
  ui_story_31050601_30_dialog_content = "¡Lo siento! Así son todos...",
  ui_story_31050601_31_dialog_content = "Está bien. Esta tampoco es la primera vez que trato con la llave inglesa Rediesel.",
  ui_story_31050601_32_dialog_content = "...",
  ui_story_31050601_33_dialog_content = "...",
  ui_story_31050601_34_dialog_content = "Entonces, eh... tu atuendo...",
  ui_story_31050601_35_dialog_content = "¡Ay! E-Es nuevo, ¿te gusta? Yo, eh... Durante el concurso, quiero...",
  ui_story_31050601_36_dialog_content = "Escuché que era un atuendo especial que podría aumentar la confianza, así que...",
  ui_story_31050601_37_dialog_content = "Quieres animar a todos y levantarles el ánimo, ¿no? ¡Pienso que es una idea genial! ¡También pareces mucho más enérgico estos días!",
  ui_story_31050601_38_dialog_content = "¡Sí! Me he estado sintiendo mucho mejor últimamente y no quiero seguir aprovechándome de la generosidad de todos... ¡Así que pensé que esta sería una buena manera de pagarles!",
  ui_story_31050601_39_dialog_content = "Pero, ¿por qué no participaste en el concurso en sí?",
  ui_story_31050601_40_dialog_content = "Bueno, si lo hiciera...",
  ui_story_31050601_41_dialog_content = "¡Guau!",
  ui_story_31050601_42_dialog_content = "¡Sí! ¡¡¡Víspera!!!",
  ui_story_31050601_43_dialog_content = "¿Mira eso? ¡No podrías pedir una actuación más perfecta! ¡Eso no era solo arte, muchachos! ¡Fue un milagro!",
  ui_story_31050601_44_dialog_content = "¡Así que recuerden votar por Eve, todos! ... Si no...",
  ui_story_31050601_45_dialog_content = "¿Quién se atreve a no hacerlo?",
  ui_story_31050601_46_dialog_content = "Esa es una posibilidad definitiva, sí...",
  ui_story_31050601_47_dialog_content = "¿Correcto? Mi hermano puede dejarse llevar un poco a veces...",
  ui_story_31050601_48_dialog_content = "¡Así que elegí quedarme fuera y animar a todos en su lugar!",
  ui_story_31050601_49_dialog_content = "Entonces, ¿qué piensas de mi atuendo?",
  ui_story_31050601_50_option_content = "¡Es genial!",
  ui_story_31050601_51_dialog_content = "¡Nunca había visto este estilo de ropa en todo Astra! ¡Es realmente llamativo!",
  ui_story_31050601_52_dialog_content = "¡Desde su diseño hasta su practicidad, es totalmente perfecto para porristas!",
  ui_story_31050601_53_dialog_content = "Tengo mucha curiosidad por saber a quién se le ocurrió este atuendo...",
  ui_story_31050601_54_dialog_content = "¡Sí yo también! ¡Este atuendo es increíble!",
  ui_story_31050601_55_dialog_content = "¡Escuché que también era bastante caro!",
  ui_story_31050601_56_option_content = "Tiene margen de mejora.",
  ui_story_31050601_57_dialog_content = "El diseño es nuevo, y nunca había visto nada igual en todo Astra...",
  ui_story_31050601_58_dialog_content = "Pero para alguien que vive en el desierto, creo que debería cubrir más el cuerpo para evitar quemaduras solares.",
  ui_story_31050601_59_dialog_content = "Y si te cayeras, tus rodillas y tobillos...",
  ui_story_31050601_60_dialog_content = "T-Realmente piensas en todo, ¿no? PlayerName? De todos modos, creo que está bien si lo uso de vez en cuando.",
  ui_story_31050601_61_dialog_content = "Después de todo, no fue fácil de conseguir. ¡No creerías lo caro que era!",
  ui_story_31050601_62_dialog_content = "No me digas que se lo compraste a Jomu.",
  ui_story_31050601_63_dialog_content = "¡No! ¡En realidad, Joanie y los demás lo robaron de la caravana Umbraton!",
  ui_story_31050601_64_dialog_content = "¡Esos Rediesel Wrench se salieron con la suya otra vez! ¡Date prisa, vamos a ver lo que nos estamos perdiendo esta vez!",
  ui_story_31050601_65_dialog_content = "Oh, no... ¡No ese lindo y pequeño atuendo deportivo! ¡Esos monstruos!",
  ui_story_31050601_66_dialog_content = "Llave Rediesel... ¡Espero que le den un buen uso!",
  ui_story_31050601_67_dialog_content = "Oye, ¿qué es eso en tu mano derecha?",
  ui_story_31050601_68_dialog_content = "¿Oh esto? Tiny One y Sinsa me ayudaron a hacerlo, ¡así que tenía algo que combinara con mi nuevo atuendo!",
  ui_story_31050601_69_dialog_content = "Se ve muy bien elaborado, pero... ¿Qué es eso? <color=#FFB400>botón</color> ¿por?",
  ui_story_31050601_70_dialog_content = "¿E-Éste?",
  ui_story_31050601_71_dialog_content = "Uh... Je, es una herramienta de autodefensa que Sinsa puso...",
  ui_story_31050601_72_dialog_content = "¿Eh?",
  ui_story_31050601_73_dialog_content = "Dice que si alguna vez estoy en peligro, todo lo que tengo que hacer es presionar este botón, y él...",
  ui_story_31050601_74_dialog_content = "¡Atención! ¡Atención! Si alguien aún no ha ensayado, ¡venga ahora mismo! ¡Nos estamos quedando sin tiempo!",
  ui_story_31050601_75_dialog_content = "¡Traje esa nueva pieza de equipo, Odi! ¿Dónde debo aparcar mi coche?",
  ui_story_31050601_76_dialog_content = "Aparca sobre tu cabeza vacía, ¿por qué no?",
  ui_story_31050601_77_dialog_content = "¡¿Para que era eso?!",
  ui_story_31050601_78_dialog_content = "¡Oh no, ya casi es hora!",
  ui_story_31050601_79_dialog_content = "¡Necesito darme prisa y practicar mis vítores! ¿Podrías quedarte y ayudarme un poco?",
  ui_story_31050601_80_dialog_content = "P-Pero yo también tengo que irme...",
  ui_story_31050601_81_dialog_content = "Tu crees <color=#FFB400>\"¡Sinsa, Sinsa, fuerte y orgullosa!\"</color> es mejor, o...",
  ui_story_31050601_82_dialog_content = "Tal vez debería usar <color=#FFB400>\"¡Rediesel el mejor! ¡Rediesel el mejor!\"</color>, ¿en lugar de?",
  ui_story_31050601_83_dialog_content = "...",
  ui_story_31050601_84_dialog_content = "Puede que haya estado aislado del mundo durante diecisiete años, pero incluso yo puedo decir que esos no son los mejores...",
  ui_story_31050601_85_dialog_content = "R-¿En serio? Pero pensé en ellos durante tanto tiempo...",
  ui_story_31050601_86_dialog_content = "¿Quizás se supone que debes emparejarlos con una linda rutina o algo así?",
  ui_story_31050601_87_dialog_content = "¿Quieres decir así?",
  ui_story_31050601_88_dialog_content = "<size=40>¡Oye!</size>",
  ui_story_31050601_89_dialog_content = "<size=40>\"¡Sinsa, Sinsa, fuerte y orgullosa!\"</size>",
  ui_story_31050601_90_dialog_content = "<color=#e8d9bb>Ta-da!</color>",
  ui_story_31050601_91_dialog_content = "(Tan lindo...)",
  ui_story_31050601_92_dialog_content = "¿O tal vez debería agregarle más? Hmm... ¿Qué haría Bárbara por algo como esto?",
  ui_story_31050601_93_dialog_content = "<size=40>¡Oye! ¡Oye!</size>",
  ui_story_31050601_94_dialog_content = "<size=40>¡¡Yo!!</size>",
  ui_story_31050601_95_dialog_content = "<size=40>\"Rediesel el más genial!\"</size>",
  ui_story_31050601_96_dialog_content = "<size=40>\"¡Rediesel el más grande!\"</size>",
  ui_story_31050601_97_dialog_content = "<size=40>¡Todos ahora!</size>",
  ui_story_31050601_98_dialog_content = "(Es demasiado lindo!!!)",
  ui_story_31050601_99_dialog_content = "<size=40>\"Rediesel el más genial!\"</size>",
  ui_story_31050601_100_dialog_content = "<size=40>\"¡Rediesel el más grande!\"</size>",
  ui_story_31050601_101_dialog_content = "<size=40>¡Dilo más fuerte! ¡Pon las manos en el aire!</size>",
  ui_story_31050601_102_dialog_content = "<size=45>\"Rediesel el mas cool!!!\"</size>",
  ui_story_31050601_103_dialog_content = "¡Todos los de atrás, levántense y griten también!",
  ui_story_31050601_104_dialog_content = "<size=48>\"Rediesel el más grande!!!\"</size>",
  ui_story_31050601_105_dialog_content = "¡Iluminemos este desierto, todos! ¡Guau!",
  ui_story_31050601_106_dialog_content = "<anim type=Shake><size=51>\"¡Rediesel el mejor! ¡Rediesel el mejor!\"</size></anim>",
  ui_story_31050601_107_dialog_content = "<size=40>¡Oye! ¡Oye!</size>",
  ui_story_31050601_108_dialog_content = "<size=40>¡Oye! ¡Oye!</size>",
  ui_story_31050601_109_dialog_content = "<size=40>¡¡Ay!!</size>",
  ui_story_31050601_110_dialog_content = "<color=#e8d9bb>¡Golpear!</color>",
  ui_story_31050601_111_dialog_content = "¡¡Ay!! ...Espera un momento... ¿\"Oww\"?",
  ui_story_31050601_112_dialog_content = "¿Eh? ¿Víspera?",
  ui_story_31050601_113_dialog_content = "PlayerName.",
  ui_story_31050601_114_dialog_content = "Urgh.",
  ui_story_31050601_115_dialog_content = "Oh no... ¡Eva! ¡Te caíste! ¿Estás bien?",
  ui_story_31050601_116_dialog_content = "¡Estoy bien! simplemente me dejé llevar...",
  ui_story_31050601_117_dialog_content = "¿Qué hace este agujero en el suelo aquí...?",
  ui_story_31050601_118_dialog_content = "<color=#e8d9bb>Bip... Bip...</color>",
  ui_story_31050601_119_dialog_content = "¿Qué es ese sonido?",
  ui_story_31050601_120_dialog_content = "Eh... Ups.",
  ui_story_31050601_121_dialog_content = "Yo...",
  ui_story_31050601_122_dialog_content = "Accidentalmente empujé el <color=#FFB400>botón</color>!",
  ui_story_31050601_123_dialog_content = "¡Correr! PlayerName!",
  ui_story_31050601_124_dialog_content = "¿Huir? Pero por qué...?",
  ui_story_31050601_125_dialog_content = "<size=45><color=#e8d9bb>¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡¡</color></size>",
  ui_story_31050601_126_dialog_content = "Haaaaa!!!",
  ui_story_31050601_127_dialog_content = "...!!!",
  ui_story_31050601_128_dialog_content = "¡Escuchen!",
  ui_story_31050601_129_dialog_content = "¡Sinsa, la guardiana de Eva, ha sido convocada ante ti!",
  ui_story_31050601_130_dialog_content = "Ahora dime...",
  ui_story_31050601_131_dialog_content = "¿Eres tú quien lastimó a mi hermana?",
  ui_story_31050601_132_dialog_content = "...",
  ui_story_31050601_133_dialog_content = "(Estoy sin palabras.)",
  ui_story_31050601_134_dialog_content = "(¿Es porque todo esto fue tan repentino? Me tomó completamente por sorpresa...)",
  ui_story_31050601_135_dialog_content = "(No eso no es.)",
  ui_story_31050601_136_dialog_content = "(La verdadera razón por la que estoy sin palabras en este momento es...)",
  ui_story_31050601_137_dialog_content = "<size=45>¡¿De dónde saliste volando, Sinsa?!?!</size>",
  ui_story_31050602_1_dialog_content = "<color=#e8d9bb>Pío, pío—</color>",
  ui_story_31050602_2_dialog_content = "Despacio ahora, Eve! El suelo aquí no está muy plano!",
  ui_story_31050602_3_dialog_content = "¡Pero es tan hermoso aquí! Solo mira los cálidos rayos de sol... y siente esa suave brisa... ¡Ah! ¡El tiempo está absolutamente perfecto!",
  ui_story_31050602_4_dialog_content = "¡Hay tantas flores y plantas hermosas que nunca había visto antes!",
  ui_story_31050602_5_dialog_content = "Estás de muy buen ánimo hoy... ¿Te has sentido mejor últimamente?",
  ui_story_31050602_6_dialog_content = "¡Mucho mejor! Mi hermano me ha estado cuidando bien, pero normalmente me quedo en mi habitación todo el día y es súper aburrido...",
  ui_story_31050602_7_dialog_content = "¿Quieres decir que te escabulliste para pasar el rato conmigo hoy?",
  ui_story_31050602_8_dialog_content = "No, ¡se lo dije antes de salir!",
  ui_story_31050602_9_dialog_content = "Eve? ¿Por qué llevas ese atuendo? ¿A dónde vas?",
  ui_story_31050602_10_dialog_content = "Voy a jugar con PlayerName! ¡Nos vemos!",
  ui_story_31050602_11_dialog_content = "¡Hey! ¿A qué hora vas a encontrarte con él? ¿A dónde van ustedes dos?",
  ui_story_31050602_12_dialog_content = "<size=45>¡Recuerda regresar a tiempo para la cena!</size>",
  ui_story_31050602_13_dialog_content = "¡Dijo que estaba bien!",
  ui_story_31050602_14_dialog_content = "Eso espero... Por cierto, ¡tu ropa está realmente bonita!",
  ui_story_31050602_15_dialog_content = "Son elegantes, encajan perfectamente y, lo más importante—",
  ui_story_31050602_16_dialog_content = "¡Te ves realmente feliz en ellas!",
  ui_story_31050602_17_dialog_content = "¡Creo que este atuendo también es genial! Quiero hacer un armario súper grande en mi habitación, ¡lleno de todo tipo de hermosas blusas y faldas!",
  ui_story_31050602_18_dialog_content = "¿Vendrás conmigo a Umbraton la próxima vez para elegir más?",
  ui_story_31050602_19_dialog_content = "¡Está bien! ¡Es un trato!",
  ui_story_31050602_20_dialog_content = "¡Vamos, aún quiero ver esa pequeña colina más adelante!",
  ui_story_31050602_21_dialog_content = "Uf...",
  ui_story_31050602_22_dialog_content = "¿Estás cansado, Eve? ¿Tu cuerpo...",
  ui_story_31050602_23_dialog_content = "Mi cuerpo está bien... ¡No te preocupes! Tomemos un descanso de cinco minutos.",
  ui_story_31050602_24_dialog_content = "¡Está bien! ¡Traje algo de alimento! También hay una cantina aquí. Bebe un poco de agua primero y extenderé la manta de picnic.",
  ui_story_31050602_25_dialog_content = "Gracias. ¿Hiciste todo esto tú mismo? ¡Wow! Tenemos sándwiches, ensalada, ¡y mucho más!",
  ui_story_31050602_26_dialog_content = "¡Oh, se supone que esta zanahoria debe cortarse en forma de flor del amanecer?! ¡Eso es muy considerado de tu parte!",
  ui_story_31050602_27_dialog_content = "S-Sí, lo entendiste... Jaja...",
  ui_story_31050602_28_dialog_content = "... ¡Y ahora, el toque... final!",
  ui_story_31050602_29_dialog_content = "PlayerName, ¡deja de cortar zanahorias ya! Has pasado por tantas canastas... Solo piensa un poco en nuestros gastos de comida para la próxima semana, ¿no?",
  ui_story_31050602_30_dialog_content = "¡No te preocupes, me aseguraré de comerlos todos!",
  ui_story_31050602_31_dialog_content = "De todos modos, hice todo esto yo mismo. Por favor, adelante y pruébalo...",
  ui_story_31050602_32_dialog_content = "¡Correcto! ¡Vamos a sentarnos primero!",
  ui_story_31050602_33_dialog_content = "¡Está bien!",
  ui_story_31050602_34_dialog_content = "La hierba es tan suave y fragante... Huele increíble cuando se mezcla con el aroma del sol.",
  ui_story_31050602_35_dialog_content = "¿Tiene olor el sol?",
  ui_story_31050602_36_dialog_content = "¡Claro! Cierra los ojos y deja que el sol bañe tu rostro.",
  ui_story_31050602_37_dialog_content = "Hmm... Es cálido. Even con mis ojos cerrados, aún puedo ver su luz dorada.",
  ui_story_31050602_38_dialog_content = "Te encanta tomar el sol, ¿verdad...",
  ui_story_31050602_39_dialog_content = "Sí, la sensación de la luz solar calentando mi cuerpo me hace sentir... vivo.",
  ui_story_31050602_40_dialog_content = "Y si me acuesto así por un rato, puedo entrar sin esfuerzo en una siesta refrescante sin siquiera darme cuenta de ello!",
  ui_story_31050602_41_dialog_content = "También empiezo a sentirme un poco somnoliento. Pero debemos recordar regresar a tiempo, ya que tu hermano podría preocuparse cuando empiece a oscurecer.",
  ui_story_31050602_42_dialog_content = "¡Hmm! ¡No te preocupes, no causaré problemas hoy!",
  ui_story_31050602_43_dialog_content = "(Es justo como dijo Eve, recostarse en el césped y echarse una buena siesta es muy relajante.)",
  ui_story_31050602_44_dialog_content = "(Hmm, hace mucho tiempo que no me relajo y descanso adecuadamente, y ha pasado un buen rato desde la última vez que intenté respirar los aromas a mi alrededor.)",
  ui_story_31050602_45_dialog_content = "<color=#828282>Crujido...</color>",
  ui_story_31050602_46_dialog_content = "... Eve?",
  ui_story_31050602_47_dialog_content = "PlayerName, ¡Estoy por aquí!",
  ui_story_31050602_48_dialog_content = "Mira, esto es un...",
  ui_story_31050602_49_dialog_content = "Ten cuidado, es muy frágil. Esta flor se llama <color=#FFB400>diente de león</color>. Sus semillas son recogidas por el viento y vuelan lejos.",
  ui_story_31050602_50_dialog_content = "¿En serio? ¿Hasta dónde vuelan y a dónde van?",
  ui_story_31050602_51_dialog_content = "Depende de la dirección del viento y qué tan fuerte sea. A veces vuelan a los prados y jardines cercanos, y otras veces vuelan a montañas, ríos y lagos lejanos.",
  ui_story_31050602_52_dialog_content = "¡Oh, recuerdo una historia sobre esto!",
  ui_story_31050602_53_dialog_content = "Algunas personas dicen que si pides un <color=#FFB400>deseo</color> en un diente de león intacto y lo soplas, tu deseo se cumplirá cuando la primera semilla aterrice.",
  ui_story_31050602_54_dialog_content = "¡De verdad! ¡Quiero intentarlo!",
  ui_story_31050602_55_dialog_content = "... ¿Qué deseo debería pedir? ¿Tienes alguna sugerencia?",
  ui_story_31050602_56_option_content = "Desea lo que más quieres.",
  ui_story_31050602_57_dialog_content = "¿Hay algo especial que quieras?",
  ui_story_31050602_58_dialog_content = "¡Oh, sí! Quiero quedarme con mi hermano, Dawn, PlayerName y todos para siempre.",
  ui_story_31050602_59_dialog_content = "Y luego seremos felices todos los días... Even incluso si no logramos algo particularmente importante, podemos vivir una vida simple y feliz.",
  ui_story_31050602_60_dialog_content = "Eso es exactamente lo que yo también quiero.",
  ui_story_31050602_61_dialog_content = "¡De verdad! Entonces, ¡realmente tenemos una conexión profunda! ¿Es este nuestro deseo compartido?",
  ui_story_31050602_62_dialog_content = "Sí, pero puedes soplar el diente de león ya que ahora eres la voz oficial de nuestro deseo.",
  ui_story_31050602_63_dialog_content = "Solo recuerda que los dientes de león solos no pueden hacer realidad tu deseo. ¡Aún necesitamos trabajar juntos y esforzarnos mucho!",
  ui_story_31050602_64_dialog_content = "Entiendo. Bueno, ¡voy a arruinarlo ahora!",
  ui_story_31050602_65_option_content = "Vive el momento.",
  ui_story_31050602_66_dialog_content = "Realmente quiero que este momento feliz dure para siempre.",
  ui_story_31050602_67_dialog_content = "¡Eso suena fantástico! Imagina si el sol nunca se pusiera, yo, Sinsa, Dawn, PlayerName y todos los demás... podríamos dar largos paseos y hacer picnics juntos, ¡por siempre!",
  ui_story_31050602_68_dialog_content = "No creo tener el aguante para eso.",
  ui_story_31050602_69_dialog_content = "Jajaja, ¡correcto! Pero entonces siempre estarías feliz, ¡sin preocuparte por nada en el mundo!",
  ui_story_31050602_70_dialog_content = "Sí, ¡sin preocupaciones en el mundo!",
  ui_story_31050602_71_dialog_content = "Oye, ¿te estás burlando de mí?!",
  ui_story_31050602_72_dialog_content = "Estoy pidiendo un deseo juntos. Solo recuerda que los dientes de león solos no pueden hacer que tu deseo se haga realidad. EveLos esfuerzos y la persistencia de todos también juegan un gran papel en ello.",
  ui_story_31050602_73_dialog_content = "No importa lo que diga la gente, siempre que aspiremos a ser felices, podemos vivir felices cada día.",
  ui_story_31050602_74_dialog_content = "No importa lo que diga alguien o incluso lo que decidan los cielos arriba...",
  ui_story_31050602_75_dialog_content = "Tienes razón. ¡Ni siquiera el destino se interpondrá en el camino de nuestro deseo!",
  ui_story_31050602_76_dialog_content = "<color=#e8d9bb>Eve cierra sus ojos y recita silenciosamente su deseo en su corazón, luego toma un suave respiro.</color>",
  ui_story_31050602_77_dialog_content = "<color=#e8d9bb>El pelusa blanca se aleja con la brisa como innumerables palabras escritas en el viento.</color>",
  ui_story_31050602_78_dialog_content = "<color=#e8d9bb>Quizás uno de sus deseos se haya hecho realidad, pero aún quedan más por cumplirse, cada uno alejándose en las semillas del diente de león.</color>"
}
return config
